import React from 'react';
import manifest from '../data/imageManifest.json';

/**
 * <Picture> — WebP (+ 640px phone variant) with the original file as fallback.
 *
 *   <Picture src="/images/sunrise.jpg" alt="" sizes="(max-width: 640px) 100vw, 480px" />
 *
 * `src` is a public path. Variants and intrinsic sizes come from
 * src/data/imageManifest.json, generated by `python3 scripts/optimize-images.py`.
 * Images missing from the manifest fall back to a plain <img>.
 * The <picture> wrapper uses `display: contents` (see index.css), so existing
 * CSS that targets `.parent img` keeps working unchanged.
 */
export default function Picture({
  src,
  alt = '',
  sizes = '100vw',
  className,
  loading = 'lazy',
  priority = false,
  ...imgProps
}) {
  const entry = manifest[src];
  const img = (
    <img
      src={src}
      alt={alt}
      className={className}
      loading={priority ? 'eager' : loading}
      decoding="async"
      fetchPriority={priority ? 'high' : undefined}
      width={entry ? entry.w : undefined}
      height={entry ? entry.h : undefined}
      {...imgProps}
    />
  );
  if (!entry) return img;

  const srcSet = entry.small ? `${entry.small} 640w, ${entry.webp} ${entry.w}w` : `${entry.webp} ${entry.w}w`;
  return (
    <picture className="ds-picture">
      <source type="image/webp" srcSet={srcSet} sizes={sizes} />
      {img}
    </picture>
  );
}

/** WebP URL for CSS backgrounds (all supported browsers decode WebP). */
export function webpUrl(src) {
  const entry = manifest[src];
  return entry ? entry.webp : src;
}
